import Phaser, { Scene } from 'phaser';
import { EventBus } from './EventBus';
import { WorkUnit, OwnerGateItem } from '../types';

// Embedded preview asset: remove this constant once the repository/public asset route is available.
const CITY_PRODUCTION_BASE = "data:image/webp;base64,";

type Building = { unit: WorkUnit; view: Phaser.GameObjects.Container };

export class CityScene extends Scene {
  workUnits: WorkUnit[] = [];
  ownerGates: OwnerGateItem[] = [];
  buildings: Building[] = [];
  agents: Phaser.GameObjects.GameObject[] = [];
  private town?: Phaser.GameObjects.Container;
  private marker?: Phaser.GameObjects.Graphics;
  private readonly W = 1920;
  private readonly H = 1280;

  constructor() { super({ key: 'CityScene' }); }

  preload() {
    this.load.image('city-production-base-v1', CITY_PRODUCTION_BASE);
  }

  init(data: { workUnits?: WorkUnit[]; ownerGates?: OwnerGateItem[] }) {
    this.workUnits = data?.workUnits ?? [];
    this.ownerGates = data?.ownerGates ?? [];
  }

  create() {
    this.cameras.main.setBackgroundColor('#0b1220');
    this.cameras.main.setBounds(0, 0, this.W, this.H);
    this.physics.world.setBounds(0, 0, this.W, this.H);
    this.renderTown();
    this.installCamera();
    this.events.once(Phaser.Scenes.Events.SHUTDOWN, this.cleanup, this);
    EventBus.emit('city-ready', this);
  }

  updateData(workUnits: WorkUnit[] = [], ownerGates: OwnerGateItem[] = []) {
    this.workUnits = workUnits;
    this.ownerGates = ownerGates;
    if (this.scene.isActive()) this.renderTown();
  }

  private idOf(unit: WorkUnit, i: number) {
    return String((unit as any).work_unit_id ?? (unit as any).WORK_UNIT_ID ?? (unit as any).id ?? `UNVERIFIED-${i + 1}`);
  }

  private colourOf(unit: WorkUnit) {
    const s = String((unit as any).status ?? (unit as any).STATUS ?? '').toUpperCase();
    if (s.includes('BLOCK')) return 0xef4444;
    if (s.includes('VERIFIED')) return 0x22c55e;
    if (s.includes('STALE')) return 0xf59e0b;
    return 0x64748b;
  }

  private renderTown() {
    this.town?.destroy(true);
    this.buildings = [];
    this.agents = [];
    this.town = this.add.container();

    const g = this.add.graphics();
    const hasProductionBase = this.textures.exists('city-production-base-v1');
    if (hasProductionBase) {
      const base = this.add.image(0, 0, 'city-production-base-v1').setOrigin(0);
      base.setDisplaySize(this.W, this.H);
      this.town.add(base);
    }
    if (!hasProductionBase) {
    // Deep night terrain: large tonal fields avoid the old checkerboard/game-board look.
    g.fillStyle(0x07111f).fillRect(0, 0, this.W, this.H);
    g.fillStyle(0x0b1c2a).fillRoundedRect(34, 34, this.W - 68, this.H - 68, 54);
    g.fillStyle(0x0d2630).fillRoundedRect(62, 62, 790, 474, 38);
    g.fillStyle(0x102332).fillRoundedRect(1068, 62, 790, 474, 38);
    g.fillStyle(0x10262d).fillRoundedRect(62, 744, 790, 474, 38);
    g.fillStyle(0x0c2230).fillRoundedRect(1068, 744, 790, 474, 38);

    // Layered boulevard with shoulders, pavements and restrained lane light.
    g.fillStyle(0x050a13, .55).fillRoundedRect(0, 548, this.W, 188, 34);
    g.fillStyle(0x111b2a).fillRoundedRect(0, 568, this.W, 148, 28);
    g.fillStyle(0x223247).fillRect(0, 582, this.W, 5).fillRect(0, 697, this.W, 5);
    g.fillStyle(0x050a13, .55).fillRoundedRect(864, 0, 192, this.H, 34);
    g.fillStyle(0x111b2a).fillRoundedRect(886, 0, 148, this.H, 28);
    g.fillStyle(0x223247).fillRect(900, 0, 5, this.H).fillRect(1015, 0, 5, this.H);
    g.lineStyle(3, 0x7dd3fc, .24);
    for (let x = 24; x < this.W; x += 96) g.lineBetween(x, 642, x + 42, 642);
    for (let y = 24; y < this.H; y += 96) g.lineBetween(960, y, 960, y + 42);

    // Civic plaza: concentric, architectural and luminous rather than a flat square.
    g.fillStyle(0x020617, .5).fillRoundedRect(754, 434, 412, 412, 54);
    g.fillStyle(0x17243a).fillRoundedRect(778, 458, 364, 364, 44);
    g.lineStyle(3, 0x38bdf8, .32).strokeRoundedRect(794, 474, 332, 332, 36);
    g.fillStyle(0x0b1324).fillCircle(960, 640, 112);
    g.lineStyle(9, 0x0ea5e9, .34).strokeCircle(960, 640, 94);
    g.fillStyle(0x38bdf8, .14).fillCircle(960, 640, 82);
    g.fillStyle(0x7dd3fc, .86).fillCircle(960, 640, 23);
    g.fillStyle(0xffffff, .9).fillCircle(954, 633, 7);
    }
    this.town.add(g);

    const districts = [
      ['INTAKE',260,210],['ROUTING',960,210],['VERIFICATION',1660,210],
      ['EVIDENCE',260,1070],['RECOVERY',960,1070],['HANDOFF',1660,1070]
    ] as const;
    districts.forEach(([name,x,y]) => {
      const label = this.add.text(x,y,name,{
        fontFamily:'Inter, sans-serif',fontSize:'17px',color:'#bae6fd',fontStyle:'bold',
        backgroundColor:'#07111fe8',padding:{x:16,y:9},letterSpacing:2
      }).setOrigin(.5).setDepth(900);
      this.town!.add(label);
    });

    // Thirteen canonical addresses occupy the generated foundation's plots.
    // The remaining south-east plot is reserved for the future Ant Nest.
    const slots = [
      {x:318,y:282},{x:812,y:282},{x:1108,y:282},{x:1588,y:282},
      {x:300,y:570},{x:606,y:570},{x:1300,y:570},{x:1612,y:570},
      {x:294,y:892},{x:612,y:892},{x:856,y:892},{x:1094,y:892},{x:1332,y:892}
    ];
    this.workUnits.slice(0, slots.length).forEach((unit,i) => {
      const id = this.idOf(unit,i);
      const {x,y} = slots[i];
      const view = this.house(x,y,id,this.colourOf(unit),i);
      view.setInteractive(new Phaser.Geom.Rectangle(-110,-100,220,210),Phaser.Geom.Rectangle.Contains);
      if (view.input) view.input.cursor = 'pointer';
      view.on('pointerover',() => this.tweens.add({targets:view,scale:1.035,duration:140,ease:'Sine.Out'}));
      view.on('pointerout',() => this.tweens.add({targets:view,scale:1,duration:160,ease:'Sine.Out'}));
      view.on('pointerdown',() => {
        this.marker?.clear().lineStyle(4,0x38bdf8).strokeRoundedRect(x-96,y-102,192,210,18);
        this.tweens.add({targets:view,scale:{from:.97,to:1.035},duration:170,yoyo:true,ease:'Sine.Out'});
        EventBus.emit('building-selected',unit);
      });
      this.buildings.push({unit,view});
      this.town!.add(view);
    });

    if (hasProductionBase) {
      const ant = this.add.container(1650, 892).setDepth(892);
      const antMark = this.add.graphics();
      antMark.fillStyle(0xf59e0b, .08).fillRoundedRect(-104, -84, 208, 174, 20);
      antMark.lineStyle(2, 0xf59e0b, .52).strokeRoundedRect(-104, -84, 208, 174, 20);
      antMark.fillStyle(0xf59e0b, .9).fillCircle(82, -62, 6);
      ant.add(antMark);
      ant.add(this.add.text(0, 104, 'ANT NEST · RESERVED', {
        fontFamily: 'Inter, sans-serif', fontSize: '12px', color: '#fde68a', fontStyle: 'bold',
        backgroundColor: '#020617e8', padding: { x: 10, y: 6 }, letterSpacing: 1
      }).setOrigin(.5));
      this.town.add(ant);
    }

    this.addAmbientLighting(slots);

    const nature = this.add.graphics();
    if (!hasProductionBase) {
    for (let i=0;i<46;i++) {
      const x=50+(i*233)%(this.W-100), y=55+(i*397)%(this.H-110);
      if (Math.abs(x-960)<210 || Math.abs(y-640)<120) continue;
      nature.fillStyle(0x020617,.45).fillEllipse(x+7,y+13,38,16);
      nature.fillStyle(0x334155).fillRoundedRect(x-3,y-1,6,24,3);
      nature.fillStyle(i%3?0x0f766e:0x15803d).fillCircle(x,y-10,19);
      nature.fillStyle(0x5eead4,.28).fillCircle(x-7,y-17,7);
    }
    for (let x=105;x<this.W;x+=190) {
      if (x>820&&x<1100) continue;
      nature.fillStyle(0x020617,.5).fillEllipse(x+6,557,28,10);
      nature.fillStyle(0x475569).fillRoundedRect(x-2,526,4,24,2);
      nature.fillStyle(0xfbbf24,.88).fillCircle(x,524,5);
      nature.fillStyle(0xfbbf24,.12).fillCircle(x,524,18);
    }
    }
    this.town.add(nature);
    this.marker=this.add.graphics().setDepth(500);
    this.town.add(this.marker);
    const cam=this.cameras.main;
    cam.centerOn(this.W/2,this.H/2);
    cam.setZoom(Math.min(cam.width/1120,cam.height/760,1));
  }

  private addAmbientLighting(slots: {x:number;y:number}[]) {
    if (!this.town) return;
    // Ambient-only light. It communicates place and touchability, never worker execution.
    const plazaGlow=this.add.circle(960,640,92,0x38bdf8,.07).setBlendMode(Phaser.BlendModes.ADD);
    this.town.add(plazaGlow);
    this.tweens.add({targets:plazaGlow,alpha:{from:.42,to:.86},scale:{from:.94,to:1.08},duration:2600,yoyo:true,repeat:-1,ease:'Sine.InOut'});

    slots.forEach(({x,y},i)=>{
      const warm=this.add.circle(x,y-5,34,0xfbbf24,.055).setBlendMode(Phaser.BlendModes.ADD).setDepth(y+1);
      const door=this.add.circle(x,y+36,12,0x38bdf8,.09).setBlendMode(Phaser.BlendModes.ADD).setDepth(y+2);
      this.town!.add([warm,door]);
      this.tweens.add({targets:[warm,door],alpha:{from:.48,to:.82},duration:2100+(i%4)*260,yoyo:true,repeat:-1,ease:'Sine.InOut',delay:i*90});
    });
  }

  private house(x:number,y:number,id:string,status:number,variant:number) {
    const c=this.add.container(x,y).setDepth(y);
    if (this.textures.exists('city-production-base-v1')) {
      const overlay=this.add.graphics();
      overlay.fillStyle(status,.055).fillRoundedRect(-104,-84,208,174,20);
      overlay.lineStyle(2,status,.48).strokeRoundedRect(-104,-84,208,174,20);
      overlay.fillStyle(status,.16).fillCircle(82,-62,16);
      overlay.fillStyle(status,.95).fillCircle(82,-62,6);
      c.add(overlay);
      const compact=id.length>22?`${id.slice(0,19)}…`:id;
      c.add(this.add.text(0,104,compact,{fontFamily:'Inter, sans-serif',fontSize:'12px',color:'#e0f2fe',fontStyle:'bold',
        backgroundColor:'#020617e8',padding:{x:10,y:6},letterSpacing:1}).setOrigin(.5));
      return c;
    }
    const walls=[0x244b63,0x433b67,0x315a55,0x5c3c4b];
    const sides=[0x153247,0x2b2850,0x21453f,0x3f2935];
    const roofs=[0x111827,0x172033,0x102a36,0x241b31];
    const g=this.add.graphics();
    // Ground shadow and lit entrance path establish depth.
    g.fillStyle(0x020617,.55).fillEllipse(10,65,190,54);
    g.fillStyle(0x334155,.75).fillRoundedRect(-21,54,42,57,9);
    g.fillStyle(0x38bdf8,.13).fillRoundedRect(-16,61,32,50,7);
    // Main volume + darker side volume create a compact architectural silhouette.
    g.fillStyle(sides[variant%sides.length]).fillRoundedRect(-70,-30,152,100,13);
    g.fillStyle(walls[variant%walls.length]).fillRoundedRect(-78,-38,145,102,13);
    g.fillStyle(0xffffff,.055).fillRoundedRect(-68,-29,10,78,4);
    // Modern asymmetric roof, varied per district.
    if (variant%2===0) {
      g.fillStyle(roofs[variant%roofs.length]).fillTriangle(-91,-31,-15,-96,83,-31);
      g.fillStyle(0x7dd3fc,.09).fillTriangle(-79,-31,-15,-84,-15,-31);
    } else {
      g.fillStyle(roofs[variant%roofs.length]).fillRoundedRect(-88,-64,164,38,10);
      g.fillStyle(0x7dd3fc,.08).fillRoundedRect(-76,-57,68,7,3);
    }
    // Warm windows and a cyan operational door keep state and ambience separate.
    [[-51,-8],[19,-8]].forEach(([wx,wy])=>{
      g.fillStyle(0x020617,.5).fillRoundedRect(wx-3,wy-3,34,34,6);
      g.fillStyle(0xfde68a,.92).fillRoundedRect(wx,wy,28,27,4);
      g.fillStyle(0xffffff,.26).fillRoundedRect(wx+4,wy+3,7,20,2);
    });
    g.fillStyle(0x071526).fillRoundedRect(-17,16,34,50,6);
    g.fillStyle(0x38bdf8,.28).fillRoundedRect(-12,21,24,40,4);
    g.fillStyle(0xe2e8f0,.9).fillCircle(7,43,2);
    g.fillStyle(status,.16).fillCircle(55,45,16);
    g.fillStyle(status).fillCircle(55,45,6);
    g.lineStyle(2,status,.78).strokeRoundedRect(-78,-38,145,102,13);
    c.add(g);
    const label=id.length>22?`${id.slice(0,19)}…`:id;
    c.add(this.add.text(0,91,label,{fontFamily:'Inter, sans-serif',fontSize:'12px',color:'#e0f2fe',fontStyle:'bold',
      backgroundColor:'#020617e8',padding:{x:10,y:6},letterSpacing:1}).setOrigin(.5));
    return c;
  }

  private installCamera() {
    let down=false, px=0, py=0;
    this.input.on('pointerdown',(p:Phaser.Input.Pointer)=>{down=true;px=p.x;py=p.y;});
    this.input.on('pointerup',()=>{down=false;});
    this.input.on('pointermove',(p:Phaser.Input.Pointer)=>{
      if(!down)return;
      const c=this.cameras.main;c.scrollX-=(p.x-px)/c.zoom;c.scrollY-=(p.y-py)/c.zoom;px=p.x;py=p.y;
    });
    this.input.on('wheel',(_p:Phaser.Input.Pointer,_o:any,_x:number,dy:number)=>{
      const c=this.cameras.main;c.setZoom(Phaser.Math.Clamp(c.zoom-dy*.0008,.42,1.5));
    });
  }

  private cleanup() {
    this.input.removeAllListeners();
    this.tweens.killAll();
    this.buildings=[];
    this.agents=[];
  }
}
